import 'alert_rules.dart';
import 'alert_state.dart';

/// Represents one meaningful alert generated by the Alert Engine.
///
/// The engine decides when an incident reaches an alert stage.
/// NotificationService is responsible for delivering the actions.
class DriverAlert {
  final String ruleId;
  final String ruleName;
  final String description;
  final AlertSeverity severity;
  final List<AlertAction> actions;
  final DateTime timestamp;
  final String message;
  final bool shouldNotify;
  final bool shouldEscalate;

  const DriverAlert({
    required this.ruleId,
    required this.ruleName,
    required this.description,
    required this.severity,
    required this.actions,
    required this.timestamp,
    required this.message,
    required this.shouldNotify,
    required this.shouldEscalate,
  });
}

/// Incident-based alert engine for Driver Safety AI.
///
/// CAMERA FRAME != EVENT != INCIDENT != NOTIFICATION.
///
/// detector.py remains the source of truth for measurements and
/// temporal event counters. This class converts those signals into
/// application-level incidents, notification stages, driver response
/// state and emergency-contact escalation.
class AlertEngine {
  final AlertStateManager _stateManager = AlertStateManager();

  // ============================================================
  // CONFIRMATION THRESHOLDS
  // ============================================================

  static const Duration drowsinessConfirmation =
      Duration(seconds: 2);

  static const Duration prolongedEyeClosureConfirmation =
      Duration(seconds: 2);

  static const Duration driverNotDetectedConfirmation =
      Duration(seconds: 3);

  static const int repeatedYawningCount =
      AlertRules.repeatedYawnCount;

  static const Duration repeatedEventWindow =
      AlertRules.repeatedYawnWindow;

  static const Duration criticalEscalationDuration =
      AlertRules.criticalEscalationDuration;

  /// Time allowed for the driver to respond to a critical
  /// in-app safety alert.
  ///
  /// If the driver explicitly selects "I'M SAFE" or "NEED HELP",
  /// the response window is no longer treated as a no-response
  /// case.
  static const Duration driverResponseWindow =
      Duration(seconds: 30);

  // ============================================================
  // YAWN EVENT TRACKING
  // ============================================================

  final List<DateTime> _yawnEvents = <DateTime>[];

  int _lastObservedYawnCount = 0;

  bool _hasObservedYawnCounter = false;

  // ============================================================
  // PUBLIC STATE ACCESS
  // ============================================================

  AlertStateManager get stateManager => _stateManager;

  // ============================================================
  // MAIN PROCESSING
  // ============================================================

  /// Processes one detector response.
  ///
  /// This can safely be called every ~250 ms because incident
  /// state prevents duplicate notifications.
  List<DriverAlert> processDetection(
    Map<String, dynamic> detectorResult, {
    DateTime? timestamp,
  }) {
    final now = timestamp ?? DateTime.now();

    final alerts = <DriverAlert>[];

    _processProlongedEyeClosure(
      detectorResult,
      now,
      alerts,
    );

    _processDrowsiness(
      detectorResult,
      now,
      alerts,
    );

    _processRepeatedYawning(
      detectorResult,
      now,
      alerts,
    );

    _processDriverNotDetected(
      detectorResult,
      now,
      alerts,
    );

    _processCriticalEscalations(
      detectorResult,
      now,
      alerts,
    );

    return alerts;
  }

  // ============================================================
  // DROWSINESS
  // ============================================================

  void _processDrowsiness(
    Map<String, dynamic> detectorResult,
    DateTime timestamp,
    List<DriverAlert> alerts,
  ) {
    final rule = AlertRules.drowsiness;

    final state = _stateManager.stateFor(rule);

    if (!rule.enabled) {
      _stateManager.clearCondition(rule);
      return;
    }

    final faceDetected =
        _boolValue(detectorResult['face_detected']);

    final fatigue =
        _stringValue(detectorResult['fatigue']).toLowerCase();

    final isDrowsy =
        faceDetected && fatigue == 'high';

    if (!isDrowsy) {
      _stateManager.clearCondition(rule);
      return;
    }

    _recordContinuousDetection(
      rule: rule,
      state: state,
      timestamp: timestamp,
    );

    if (!state.hasBeenActiveForAt(
      drowsinessConfirmation,
      timestamp,
    )) {
      return;
    }

    _addIncidentAlertIfNeeded(
      rule: rule,
      state: state,
      timestamp: timestamp,
      message:
          'Driver drowsiness detected. Please stay alert and keep your attention on the road.',
      alerts: alerts,
    );
  }

  // ============================================================
  // PROLONGED BILATERAL EYE CLOSURE
  // ============================================================

  void _processProlongedEyeClosure(
    Map<String, dynamic> detectorResult,
    DateTime timestamp,
    List<DriverAlert> alerts,
  ) {
    final rule = AlertRules.prolongedEyeClosure;

    final state = _stateManager.stateFor(rule);

    if (!rule.enabled) {
      _stateManager.clearCondition(rule);
      return;
    }

    final closedDuration =
        _doubleValue(detectorResult['closed_duration']);

    final leftEye =
        _stringValue(detectorResult['left_eye']).toLowerCase();

    final rightEye =
        _stringValue(detectorResult['right_eye']).toLowerCase();

    final eyes =
        _stringValue(detectorResult['eyes']).toLowerCase();

    final bilateralClosed =
        leftEye == 'closed' &&
        rightEye == 'closed';

    final detectorConfirmsBilateralClosure =
        bilateralClosed ||
        (
          eyes == 'closed' &&
          leftEye != 'open' &&
          rightEye != 'open'
        );

    if (!detectorConfirmsBilateralClosure) {
      _stateManager.clearCondition(rule);
      return;
    }

    _recordContinuousDetection(
      rule: rule,
      state: state,
      timestamp: timestamp,
    );

    if (closedDuration <
        AlertRules.longEyeClosureSeconds) {
      return;
    }

    if (!state.hasBeenActiveForAt(
      prolongedEyeClosureConfirmation,
      timestamp,
    )) {
      return;
    }

    _addIncidentAlertIfNeeded(
      rule: rule,
      state: state,
      timestamp: timestamp,
      message:
          'Prolonged bilateral eye closure detected. Please keep your eyes on the road.',
      alerts: alerts,
    );
  }

  // ============================================================
  // REPEATED YAWNING
  // ============================================================

  void _processRepeatedYawning(
    Map<String, dynamic> detectorResult,
    DateTime timestamp,
    List<DriverAlert> alerts,
  ) {
    final rule = AlertRules.repeatedYawning;

    final state = _stateManager.stateFor(rule);

    if (!rule.enabled) {
      _stateManager.clearCondition(rule);
      return;
    }

    final currentYawnCount =
        _intValue(detectorResult['yawn_count']);

    if (!_hasObservedYawnCounter) {
      _lastObservedYawnCount =
          currentYawnCount;

      _hasObservedYawnCounter = true;
    } else if (
        currentYawnCount <
        _lastObservedYawnCount
    ) {
      // Detector/session counter reset.
      // The reset is not an event.
      _lastObservedYawnCount =
          currentYawnCount;

      _yawnEvents.clear();

      _stateManager.clearCondition(rule);

      return;
    } else if (
        currentYawnCount >
        _lastObservedYawnCount
    ) {
      final newEvents =
          currentYawnCount -
          _lastObservedYawnCount;

      for (int i = 0; i < newEvents; i++) {
        _yawnEvents.add(timestamp);

        state.recordEvent(timestamp);
      }

      _lastObservedYawnCount =
          currentYawnCount;
    }

    _removeExpiredYawnEvents(timestamp);

    if (_yawnEvents.length <
        repeatedYawningCount) {
      _stateManager.clearCondition(rule);
      return;
    }

    if (!state.isActive) {
      _stateManager.startNewIncident(
        rule,
        timestamp: timestamp,
      );
    }

    _addIncidentAlertIfNeeded(
      rule: rule,
      state: state,
      timestamp: timestamp,
      message:
          'Repeated yawning detected. Please take a break if you are feeling tired.',
      alerts: alerts,
    );
  }

  void _removeExpiredYawnEvents(
    DateTime timestamp,
  ) {
    _yawnEvents.removeWhere(
      (eventTime) {
        return timestamp
                .difference(eventTime) >
            repeatedEventWindow;
      },
    );
  }

  // ============================================================
  // DRIVER NOT DETECTED
  // ============================================================

  /// Sustained face absence generates a High alert.
  ///
  /// If the absence continues for approximately three minutes,
  /// the critical escalation path can notify the emergency contact.
  void _processDriverNotDetected(
    Map<String, dynamic> detectorResult,
    DateTime timestamp,
    List<DriverAlert> alerts,
  ) {
    final rule =
        AlertRules.driverNotDetected;

    final state =
        _stateManager.stateFor(rule);

    if (!rule.enabled) {
      _stateManager.clearCondition(rule);
      return;
    }

    final faceDetected =
        _boolValue(detectorResult['face_detected']);

    if (faceDetected) {
      _stateManager.clearCondition(rule);
      return;
    }

    _recordContinuousDetection(
      rule: rule,
      state: state,
      timestamp: timestamp,
    );

    final detectorMissingDuration =
        _doubleValue(
          detectorResult[
            'face_not_detected_duration'
          ],
        );

    final engineMissingDuration =
        state
            .activeDurationAt(timestamp)
            .inMilliseconds /
        1000.0;

    final effectiveMissingDuration =
        detectorMissingDuration >
                engineMissingDuration
            ? detectorMissingDuration
            : engineMissingDuration;

    if (effectiveMissingDuration <
        driverNotDetectedConfirmation
            .inSeconds) {
      return;
    }

    _addIncidentAlertIfNeeded(
      rule: rule,
      state: state,
      timestamp: timestamp,
      message:
          'Driver face has not been detected continuously. Please remain visible to the camera.',
      alerts: alerts,
    );
  }

  // ============================================================
  // CRITICAL ESCALATION
  // ============================================================

  void _processCriticalEscalations(
    Map<String, dynamic> detectorResult,
    DateTime timestamp,
    List<DriverAlert> alerts,
  ) {
    _processCriticalEscalationForRule(
      rule: AlertRules.drowsiness,
      timestamp: timestamp,
      alerts: alerts,
    );

    _processCriticalEscalationForRule(
      rule: AlertRules.prolongedEyeClosure,
      timestamp: timestamp,
      alerts: alerts,
    );

    _processDriverNotDetectedCritical(
      detectorResult,
      timestamp,
      alerts,
    );
  }

  /// Handles emergency-contact escalation for an active critical
  /// incident.
  ///
  /// The critical alert itself is generated first.
  ///
  /// Then:
  ///
  ///   Critical alert
  ///        ↓
  ///   Driver response window
  ///        ↓
  ///   I'M SAFE    -> stop escalation
  ///   NEED HELP   -> emergency contact email
  ///   NO RESPONSE -> emergency contact email
  ///
  /// The same incident can generate the emergency-contact email
  /// only once.
  void _processCriticalEscalationForRule({
    required AlertRule rule,
    required DateTime timestamp,
    required List<DriverAlert> alerts,
  }) {
    if (!rule.enabled ||
        rule.severity !=
            AlertSeverity.critical) {
      return;
    }

    if (!_stateManager.isActive(rule.id)) {
      return;
    }

    final state =
        _stateManager.stateFor(rule);

    if (!state.notificationSent) {
      return;
    }

    if (state.acknowledged) {
      return;
    }

    if (state.emergencyContactEmailSent) {
      return;
    }

    // ----------------------------------------------------------
    // DRIVER REQUESTED HELP
    // ----------------------------------------------------------

    if (state.driverRequestedHelp) {
      _createEmergencyContactEmailAlert(
        rule: rule,
        state: state,
        timestamp: timestamp,
        alerts: alerts,
        reason:
            'The driver explicitly selected "NEED HELP".',
      );

      return;
    }

    // ----------------------------------------------------------
    // NO RESPONSE
    // ----------------------------------------------------------

    if (!state.driverResponseTimedOut) {
      if (state.responseDeadlineExpiredAt(
        timestamp,
      )) {
        state.markDriverResponseTimedOut(
          timestamp,
        );
      }
    }

    if (state.hasNoDriverResponse) {
      _createEmergencyContactEmailAlert(
        rule: rule,
        state: state,
        timestamp: timestamp,
        alerts: alerts,
        reason:
            'The driver did not respond to the critical safety alert within the response window.',
      );
    }
  }

  /// Driver-not-detected has a special critical threshold because
  /// the initial rule is High.
  ///
  /// Once the driver has been continuously absent for approximately
  /// three minutes, the incident can escalate to the emergency
  /// contact if there has been no driver response.
  void _processDriverNotDetectedCritical(
    Map<String, dynamic> detectorResult,
    DateTime timestamp,
    List<DriverAlert> alerts,
  ) {
    final rule =
        AlertRules.driverNotDetected;

    final state =
        _stateManager.stateFor(rule);

    if (!rule.enabled ||
        !state.isActive) {
      return;
    }

    if (_boolValue(
      detectorResult['face_detected'],
    )) {
      return;
    }

    if (state.emergencyContactEmailSent) {
      return;
    }

    if (state.acknowledged) {
      return;
    }

    final detectorMissingDuration =
        _doubleValue(
          detectorResult[
            'face_not_detected_duration'
          ],
        );

    final engineMissingDuration =
        state
            .activeDurationAt(timestamp)
            .inMilliseconds /
        1000.0;

    final effectiveMissingDuration =
        detectorMissingDuration >
                engineMissingDuration
            ? detectorMissingDuration
            : engineMissingDuration;

    const double criticalAbsenceSeconds =
        180.0;

    if (effectiveMissingDuration <
        criticalAbsenceSeconds) {
      return;
    }

    if (!state.driverResponseTimedOut) {
      if (state.responseDeadlineExpiredAt(
        timestamp,
      )) {
        state.markDriverResponseTimedOut(
          timestamp,
        );
      }
    }

    // For Driver Not Detected, there may not be a visible driver
    // available to press "I'M SAFE". Therefore sustained absence
    // beyond the critical threshold is itself sufficient to trigger
    // emergency-contact email.
    //
    // The Alert Engine still records the incident and prevents
    // repeated emergency emails.
    _createEmergencyContactEmailAlert(
      rule: rule,
      state: state,
      timestamp: timestamp,
      alerts: alerts,
      reason:
          'Driver has not been detected continuously for approximately 3 minutes.',
    );
  }

  // ============================================================
  // EMERGENCY CONTACT ALERT
  // ============================================================

  void _createEmergencyContactEmailAlert({
    required AlertRule rule,
    required AlertState state,
    required DateTime timestamp,
    required List<DriverAlert> alerts,
    required String reason,
  }) {
    // Mark BEFORE returning the alert so another 250-ms frame
    // cannot generate another emergency email for the same incident.
    state.markEmergencyContactEmailSent(
      timestamp,
    );

    alerts.add(
      DriverAlert(
        ruleId: AlertRules.alertEscalation.id,
        ruleName:
            AlertRules.alertEscalation.name,
        description:
            AlertRules.alertEscalation.description,
        severity: AlertSeverity.critical,
        actions: const [
          AlertAction.emergencyContactEmail,
        ],
        timestamp: timestamp,
        message:
            'Emergency escalation: $reason Please check on the driver immediately.',
        shouldNotify: true,
        shouldEscalate: true,
      ),
    );
  }

  // ============================================================
  // INITIAL INCIDENT ALERT
  // ============================================================

  void _addIncidentAlertIfNeeded({
    required AlertRule rule,
    required AlertState state,
    required DateTime timestamp,
    required String message,
    required List<DriverAlert> alerts,
  }) {
    if (!rule.enabled) {
      return;
    }

    // One notification per active incident.
    if (state.notificationSent) {
      return;
    }

    if (rule.severity ==
        AlertSeverity.critical) {
      state.markCriticalNotificationSent(
        timestamp,
      );

      state.markNotificationSent(
        timestamp,
      );

      // Start a real driver response window.
      state.startDriverResponseWindow(
        timestamp.add(
          driverResponseWindow,
        ),
      );
    } else if (
        rule.actions.contains(
          AlertAction.email,
        )
    ) {
      if (!state.recordEmailStage(
        timestamp,
      )) {
        return;
      }
    } else {
      state.markNotificationSent(
        timestamp,
      );
    }

    alerts.add(
      DriverAlert(
        ruleId: rule.id,
        ruleName: rule.name,
        description: rule.description,
        severity: rule.severity,
        actions: _actionsForRule(rule),
        timestamp: timestamp,
        message: message,
        shouldNotify: true,
        shouldEscalate: false,
      ),
    );
  }

  // ============================================================
  // NOTIFICATION POLICY
  // ============================================================

  /// Returns the active notification actions for the rule.
  ///
  /// The actual rule definitions remain the primary configuration.
  ///
  /// Current architecture:
  ///
  /// Warning:
  ///   In-app
  ///
  /// High:
  ///   In-app + email
  ///
  /// Critical:
  ///   In-app + email + driver acknowledgement
  ///
  /// Emergency escalation:
  ///   Emergency-contact email
  List<AlertAction> _actionsForRule(
    AlertRule rule,
  ) {
    return List<AlertAction>.from(
      rule.actions,
    );
  }

  // ============================================================
  // DRIVER RESPONSE
  // ============================================================

  /// Records the driver's "I'M SAFE" response.
  ///
  /// This is a real explicit response.
  ///
  /// It does not erase the incident from history.
  /// It only prevents unresolved-incident escalation.
  void markDriverAcknowledgement({
    required String ruleId,
    DateTime? timestamp,
  }) {
    final now =
        timestamp ?? DateTime.now();

    final state =
        _stateManager.stateForId(ruleId);

    if (state == null ||
        !state.isActive) {
      return;
    }

    state.markAcknowledged(now);
  }

  /// Records the driver's "NEED HELP" response.
  ///
  /// The actual emergency-contact email is generated by the next
  /// engine processing cycle so that all external notification
  /// actions continue through DriverAlert/NotificationService.
  void markDriverRequestedHelp({
    required String ruleId,
    DateTime? timestamp,
  }) {
    final now =
        timestamp ?? DateTime.now();

    final state =
        _stateManager.stateForId(ruleId);

    if (state == null ||
        !state.isActive) {
      return;
    }

    state.markDriverRequestedHelp(
      now,
    );
  }

  /// Evaluates whether the driver's response deadline has expired.
  ///
  /// This does not invent a response.
  /// It only records NO RESPONSE after the actual deadline passes.
  void processDriverResponseTimeout({
    required String ruleId,
    DateTime? timestamp,
  }) {
    final now =
        timestamp ?? DateTime.now();

    final state =
        _stateManager.stateForId(ruleId);

    if (state == null ||
        !state.isActive) {
      return;
    }

    state.markDriverResponseTimedOut(
      now,
    );
  }

  /// Returns whether the driver explicitly responded.
  bool driverResponded(
    String ruleId,
  ) {
    return _stateManager
        .hasDriverResponded(ruleId);
  }

  /// Returns whether the driver explicitly requested help.
  bool driverRequestedHelp(
    String ruleId
  ) {
    return _stateManager
        .driverRequestedHelp(ruleId);
  }

  /// Returns whether the driver response window expired without
  /// an explicit response.
  bool driverResponseTimedOut(
    String ruleId
  ) {
    return _stateManager
        .hasNoDriverResponse(ruleId);
  }

  /// Returns whether the response deadline has expired at [timestamp].
  bool driverResponseDeadlineExpired(
    String ruleId, {
    DateTime? timestamp,
  }) {
    return _stateManager
        .responseDeadlineExpiredAt(
      ruleId,
      timestamp ?? DateTime.now(),
    );
  }

  // ============================================================
  // RIDE LIFECYCLE
  // ============================================================

  void startNewRide() {
    _stateManager.resetForNewRide();

    _yawnEvents.clear();

    _lastObservedYawnCount = 0;

    _hasObservedYawnCounter = false;
  }

  void resetNotificationStates() {
    _stateManager
        .resetNotificationStates();
  }

  Map<String, AlertState>
      getStateSnapshot() {
    return _stateManager.snapshot();
  }

  // ============================================================
  // CONTINUOUS DETECTION
  // ============================================================

  void _recordContinuousDetection({
    required AlertRule rule,
    required AlertState state,
    required DateTime timestamp,
  }) {
    if (!state.isActive) {
      _stateManager.startNewIncident(
        rule,
        timestamp: timestamp,
      );

      return;
    }

    _stateManager.recordDetection(
      rule,
      timestamp: timestamp,
    );
  }

  // ============================================================
  // VALUE HELPERS
  // ============================================================

  static String _stringValue(
    dynamic value,
  ) {
    if (value == null) {
      return '';
    }

    return value.toString().trim();
  }

  static double _doubleValue(
    dynamic value,
  ) {
    if (value == null) {
      return 0.0;
    }

    if (value is num) {
      return value.toDouble();
    }

    return double.tryParse(
          value.toString().trim(),
        ) ??
        0.0;
  }

  static int _intValue(
    dynamic value,
  ) {
    if (value == null) {
      return 0;
    }

    if (value is int) {
      return value;
    }

    if (value is num) {
      return value.toInt();
    }

    return int.tryParse(
          value.toString().trim(),
        ) ??
        0;
  }

  static bool _boolValue(
    dynamic value,
  ) {
    if (value is bool) {
      return value;
    }

    if (value is num) {
      return value != 0;
    }

    if (value is String) {
      final normalized =
          value.trim().toLowerCase();

      if (normalized == 'true' ||
          normalized == 'yes' ||
          normalized == '1') {
        return true;
      }

      if (normalized == 'false' ||
          normalized == 'no' ||
          normalized == '0') {
        return false;
      }
    }

    return false;
  }
}